#include <rdma/rdma_cma.h>
#include <netinet/in.h>

int is_rdma_ip_valid(__be32 addr) {
    struct rdma_cm_id *id;
    struct sockaddr_in sin;
    int ret;

    id = rdma_create_id(NULL, NULL, 0);
    if (!id)
        return -ENOMEM;

    memset(&sin, 0, sizeof(sin));
    sin.sin_family = AF_INET;
    sin.sin_addr = addr;
    sin.sin_port = htons(0);

    ret = rdma_bind_addr(id, (struct sockaddr *)&sin);
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

    rdma_destroy_id(id);
    return 0;
}

int rdma_is_valid_ip_address(__be32 addr) {
    struct rdma_cm_id *id;
    struct sockaddr_in sin;
    int ret;

    id = rdma_create_id(NULL, NULL, RDMA_PS_TCP, IB_QPT_RC);
    if (IS_ERR(id)) {
        return PTR_ERR(id);
    }

    memset(&sin, 0, sizeof(sin));
    sin.sin_family = AF_INET;
    sin.sin_addr = addr;
    sin.sin_port = htons(0); // Use ephemeral port

    ret = rdma_bind_addr(id, (struct sockaddr *)&sin);
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

    if (id->device->rdma_dev_addr.driver_type != RDMA_DRIVER_IBA) {
        rdma_destroy_id(id);
        return -EINVAL;
    }

    rdma_destroy_id(id);
    return 0;
}

