int check_rdma_ip_validity(__be32 addr) {
    struct rdma_id *id;
    int ret;

    id = rdma_create_id(CSIDriver, NULL, RDMA_PS_TCP);
    if (IS_ERR(id))
        return PTR_ERR(id);

    ret = rdma_bind_addr(id, &addr, htons(0));
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

