    }

    rdma_destroy_id(id);
    return 0;
}

#include <rdma/rdma_cm.h>
#include <netinet/in.h>
#include <stdio.h>

int is_rdma_ip_valid(__be32 addr) {
    struct rdma_id *id;
    struct sockaddr_in ip_addr;
    int ret;

    id = rdma_create_id(NULL, NULL, NULL, RDMA_PS_TCP);
    if (!id)
        return -ENOMEM;

    memset(&ip_addr, 0, sizeof(ip_addr));
    ip_addr.sin_family = AF_INET;
    ip_addr.sin_addr = addr;
    ip_addr.sin_port = htons(0);

    ret = rdma_bind_addr(id, (struct sockaddr *)&ip_addr);
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

    // If binding succeeded, the address is valid for RDMA
    rdma_destroy_id(id);
    return 0;
}
